diff --git a/zig-parquet/src/core/format/metadata.zig b/zig-parquet/src/core/format/metadata.zig
index 3a2a081..5bbe036 100644
--- a/zig-parquet/src/core/format/metadata.zig
+++ b/zig-parquet/src/core/format/metadata.zig
@@ -21,8 +21,25 @@ pub const FileMetaData = struct {

     const Self = @This();

+    /// Free everything parse() allocated. Fields still at their defaults are skipped,
+    /// so this is safe on a partially filled value. Leaves `self` empty.
+    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
+        for (self.schema) |*elem| freeSchemaElement(allocator, elem);
+        allocator.free(self.schema);
+        for (self.row_groups) |*rg| freeRowGroup(allocator, rg);
+        allocator.free(self.row_groups);
+        if (self.key_value_metadata) |kvs| {
+            for (kvs) |*kv| freeKeyValue(allocator, kv);
+            allocator.free(kvs);
+        }
+        if (self.created_by) |cb| allocator.free(cb);
+        self.* = .{};
+    }
+
     pub fn parse(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !Self {
         var meta = Self{};
+        // Frees whatever has been assigned to `meta` so far if a later field fails.
+        errdefer meta.deinit(allocator);
         reader.resetFieldTracking();

         while (try reader.readFieldHeader()) |field| {
@@ -31,9 +48,15 @@ pub const FileMetaData = struct {
                 2 => {
                     const list_header = try reader.readListHeader();
                     try reader.checkListFits(list_header.size);
-                    var schema_list = try allocator.alloc(SchemaElement, list_header.size);
-                    for (0..list_header.size) |i| {
-                        schema_list[i] = try SchemaElement.parse(allocator, reader);
+                    const schema_list = try allocator.alloc(SchemaElement, list_header.size);
+                    var parsed: usize = 0;
+                    errdefer {
+                        for (schema_list[0..parsed]) |*elem| freeSchemaElement(allocator, elem);
+                        allocator.free(schema_list);
+                    }
+                    for (schema_list) |*slot| {
+                        slot.* = try SchemaElement.parse(allocator, reader);
+                        parsed += 1;
                     }
                     meta.schema = schema_list;
                 },
@@ -41,18 +64,30 @@ pub const FileMetaData = struct {
                 4 => {
                     const list_header = try reader.readListHeader();
                     try reader.checkListFits(list_header.size);
-                    var row_groups_list = try allocator.alloc(RowGroup, list_header.size);
-                    for (0..list_header.size) |i| {
-                        row_groups_list[i] = try RowGroup.parse(allocator, reader);
+                    const row_groups_list = try allocator.alloc(RowGroup, list_header.size);
+                    var parsed: usize = 0;
+                    errdefer {
+                        for (row_groups_list[0..parsed]) |*rg| freeRowGroup(allocator, rg);
+                        allocator.free(row_groups_list);
+                    }
+                    for (row_groups_list) |*slot| {
+                        slot.* = try RowGroup.parse(allocator, reader);
+                        parsed += 1;
                     }
                     meta.row_groups = row_groups_list;
                 },
                 5 => {
                     const list_header = try reader.readListHeader();
                     try reader.checkListFits(list_header.size);
-                    var kvs = try allocator.alloc(KeyValue, list_header.size);
-                    for (0..list_header.size) |i| {
-                        kvs[i] = try KeyValue.parse(allocator, reader);
+                    const kvs = try allocator.alloc(KeyValue, list_header.size);
+                    var parsed: usize = 0;
+                    errdefer {
+                        for (kvs[0..parsed]) |*kv| freeKeyValue(allocator, kv);
+                        allocator.free(kvs);
+                    }
+                    for (kvs) |*slot| {
+                        slot.* = try KeyValue.parse(allocator, reader);
+                        parsed += 1;
                     }
                     meta.key_value_metadata = kvs;
                 },
@@ -102,3 +137,41 @@ pub const FileMetaData = struct {
         try writer.writeStructEnd();
     }
 };
+
+// Element-level frees used by FileMetaData.deinit and the partial-parse errdefers.
+// Each mirrors the allocations made by the matching parse(); see DynamicReader.deinit.
+
+fn freeSchemaElement(allocator: std.mem.Allocator, elem: *SchemaElement) void {
+    if (elem.name.len > 0) allocator.free(elem.name);
+    if (elem.logical_type) |lt| switch (lt) {
+        .geometry => |g| if (g.crs) |crs| allocator.free(crs),
+        .geography => |g| if (g.crs) |crs| allocator.free(crs),
+        else => {},
+    };
+    elem.* = .{};
+}
+
+fn freeColumnChunk(allocator: std.mem.Allocator, col: *row_group_mod.ColumnChunk) void {
+    if (col.file_path) |fp| allocator.free(fp);
+    if (col.meta_data) |*md| {
+        allocator.free(md.encodings);
+        for (md.path_in_schema) |path| allocator.free(path);
+        allocator.free(md.path_in_schema);
+        if (md.statistics) |*stats| stats.deinit(allocator);
+        if (md.geospatial_statistics) |*geo| geo.deinit(allocator);
+    }
+    col.* = .{};
+}
+
+fn freeRowGroup(allocator: std.mem.Allocator, rg: *RowGroup) void {
+    for (rg.columns) |*col| freeColumnChunk(allocator, col);
+    allocator.free(rg.columns);
+    if (rg.sorting_columns) |sc| allocator.free(sc);
+    rg.* = .{};
+}
+
+fn freeKeyValue(allocator: std.mem.Allocator, kv: *KeyValue) void {
+    if (kv.key.len > 0) allocator.free(kv.key);
+    if (kv.value) |v| allocator.free(v);
+    kv.* = .{};
+}
diff --git a/zig-parquet/src/core/nested.zig b/zig-parquet/src/core/nested.zig
index 52b2cf4..b54db9a 100644
--- a/zig-parquet/src/core/nested.zig
+++ b/zig-parquet/src/core/nested.zig
@@ -417,6 +417,7 @@ fn assembleRecursive(
                 }

                 const item = try assembleRecursive(element, ctx, def_threshold + 1, rep_threshold + 1, depth + 1);
+                errdefer item.deinit(ctx.allocator);
                 try items.append(ctx.allocator, item);
                 first = false;
             }
@@ -496,7 +497,9 @@ fn assembleRecursive(

             for (s.fields) |schema_field| {
                 const field_value = try assembleRecursive(schema_field.node, ctx, def_threshold, rep_threshold, depth + 1);
+                errdefer field_value.deinit(ctx.allocator);
                 const name_copy = try ctx.allocator.dupe(u8, schema_field.name);
+                errdefer ctx.allocator.free(name_copy);
                 try fields.append(ctx.allocator, .{ .name = name_copy, .value = field_value });
                 ctx.column_index += schema_field.node.countLeafColumns();
             }
@@ -704,3 +707,49 @@ test "assembleValues not enough columns returns error" {

     try std.testing.expectError(error.NotEnoughColumns, assembleValues(allocator, &schema, &slices, 1));
 }
+
+test "assembleValues frees partial values on OOM" {
+    const allocator = std.testing.allocator;
+
+    const id_node = SchemaNode{ .int64 = .{} };
+    const tag_node = SchemaNode{ .byte_array = .{} };
+    const tags_node = SchemaNode{ .list = &tag_node };
+    const schema = SchemaNode{ .struct_ = .{
+        .fields = &[_]SchemaNode.Field{
+            .{ .name = "id", .node = &id_node },
+            .{ .name = "tags", .node = &tags_node },
+        },
+    } };
+
+    const tags = [_]Value{ .{ .bytes_val = "a" }, .{ .bytes_val = "bb" } };
+    const fields = [_]Value.FieldValue{
+        .{ .name = "id", .value = .{ .int64_val = 7 } },
+        .{ .name = "tags", .value = .{ .list_val = &tags } },
+    };
+    const value = Value{ .struct_val = &fields };
+
+    var columns = try flattenValue(allocator, &schema, value);
+    defer columns.deinit();
+
+    var slices: [2]FlatColumnSlice = undefined;
+    for (columns.columns.items, 0..) |col, i| {
+        slices[i] = .{ .values = col.values.items, .def_levels = col.def_levels.items, .rep_levels = col.rep_levels.items };
+    }
+
+    // Fail each allocation in turn. Every failing run must free what it built;
+    // std.testing.allocator reports any leak from the backing allocator.
+    var succeeded = false;
+    var fail_index: usize = 0;
+    while (fail_index < 64) : (fail_index += 1) {
+        var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = fail_index });
+        const rows = assembleValues(failing.allocator(), &schema, &slices, 1) catch |err| {
+            try std.testing.expectEqual(error.OutOfMemory, err);
+            continue;
+        };
+        for (rows) |v| v.deinit(failing.allocator());
+        failing.allocator().free(rows);
+        succeeded = true;
+        break;
+    }
+    try std.testing.expect(succeeded);
+}
### R2. Zig 0.16 API gotchas (from AGENTS.md)

- `std.ArrayList(T)`: init with `.empty`, pass the allocator to every method (`append(gpa, x)`,
  `deinit(gpa)`, `toOwnedSlice(gpa)`). `std.ArrayListUnmanaged(T)` is the same type family.
- I/O goes through `std.Io` (`io` parameter; tests use `std.testing.io`). In-memory writers:
  `std.Io.Writer.Allocating`.
- `arena.reset(.free_all)` / `arena.reset(.retain_capacity)`, never `reset()`.
- Enums from ints: `std.enums.fromInt(E, v) orelse return error.X`.
- Tests use `std.testing.allocator`, which detects leaks and double frees. Never switch a test to
  another allocator to make it pass.

### R3. Dual-version rules (0.16 **and** 0.17 must both compile every line)

| never write | write instead |
|---|---|
| `[_]T{v} ** n`, `.{v} ** n` | `@as([n]T, @splat(v))`, or `var a: [n]T = @splat(v);` |
| `"abc" ** n` | `comptime repeat.bytes("abc", n)` (`src/repeat.zig`) |
| `@cImport` / `@cInclude` | hand-written `const c = struct { extern fn ...; }` |
| `allocator.dupeZ(u8, x)` | `allocator.dupeSentinel(u8, x, 0)` |
| `std.hash.crc.Crc32`, `crc.@"CRC-32/ISO-HDLC"` | `std.hash.Crc32` |
| `b.args` / `run.addPassthruArgs()` in build.zig | `passArgs(b, run)` helper (task 1.2) |
| `@backingInt`, `@fromBackingInt` | `@intFromEnum`, `@enumFromInt` |
| `allocator.print(...)`, `allocator.printSentinel(...)` | `std.fmt.allocPrint(...)`, `std.fmt.allocPrintSentinel(...)` |
| `std.heap.SafeAllocator`, `std.heap.GeneralPurposeAllocator` | `std.heap.DebugAllocator(.{})` |
| `std.meta.fields`, `std.meta.Int`, `std.meta.Tag` (new uses) | explicit types / `switch (T)` |

- **`zig fmt` only with 0.16** (`make fmt ZIG=<Z16>`). 0.17's fmt rewrites builtins to 0.17-only
  spellings. Do not let an editor format with 0.17.
- Do not follow the `zig-0-17` skill or main's 0.17-only code for spellings. Use the table above.
- Version gates (`builtin.zig_version`) are **not** allowed in `src/`. If you hit a 0.16/0.17
  difference not in the table, **stop and ask**.

### R4. Hardening rules (HARDENING.md, non-negotiable)

- No `@intCast` on anything derived from file data or user input. Use `safe.cast`, `safe.castTo`,
  `safe.slice`, `safe.get`.
- `@truncate` only right after a mask or `& 7`-style reduction, with a comment saying why it fits.
- `catch unreachable` only with an inline comment stating the invariant.
- Checked arithmetic (`std.math.add`/`mul`) for sizes from data.
- A fast path either does **one up-front bounds check per page/run** and then indexes freely, or
  **returns null so the existing general path runs**. Never rely on ReleaseFast removing checks.
- For malformed input, the fast path must produce the same error (or the same lenient result) as the
  old code. When unsure, fall back to the old path.

